import math
from typing import List

class CombinationCalculator:
    MAX_N = 63
    INF = float("inf")

    def __init__(self, datas: List[str]):
        self._datas = datas

    @staticmethod
    def count(n: int, m: int) -> int:
        if m == 0 or n == m:
            return 1
        return math.factorial(n) // (math.factorial(n - m) * math.factorial(m))

    @staticmethod
    def count_all(n: int) -> int:
        if n < 0 or n > CombinationCalculator.MAX_N:
            return False
        if n == CombinationCalculator.MAX_N:
            return CombinationCalculator.INF
        return (1 << n) - 1

    def select(self, m: int) -> List[List[str]]:
        result = []
        self._select(0, [None] * m, 0, result)
        return result

    def select_all(self) -> List[List[str]]:
        result = []
        for i in range(1, len(self.datas) + 1):
            result.extend(self.select(i))
        return result

    @property
    def datas(self) -> List[str]:
        return self._datas

    def _select(self, data_index: int, result_list: List[str], result_index: int, result: List[List[str]]):
        result_len = len(result_list)
        result_count = result_index + 1
        if result_count > result_len:
            result.append(result_list.copy())
            return

        for i in range(data_index, len(self.datas) + result_count - result_len):
            result_list[result_index] = self.datas[i]
            self._select(i + 1, result_list, result_index + 1, result)
